int amt_GetOpenOffice(int k)
{
    AMTREC o;

    if (k == 0)
        return 0;
    if (k >= 0x1b)
        k = 0x1b;
    else if (k <= 0)
        return k;
    do {
        if (amt_GetFirstOffice(k, &o) != 0 && o.state == 3 && o.cnt <= 1)
            return k;
        k--;
    } while (k > 0);
    return k;
}
